import java.net.URI
import java.net.http.HttpClient
import java.net.http.HttpRequest
import java.net.http.HttpResponse
import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import java.time.Duration

def CEGID_URL = "https://anett-hru.cegid.com/hru/hrux_c47e.jsp"
def TOKEN_ID = "MIDPOINT"
def CDVUE = "MIDPOINT"
def OUTPUT_PATH = "/opt/midpoint/var/import/CEGID.csv"
def REJECTED_OUTPUT_PATH = "/opt/midpoint/var/import/CEGID_rejetes.csv"
def RETRY_ATTEMPTS = 3
def RETRY_DELAY_MS = 5000
// NOTE : format confirme par un exemple reel de reponse HRUX (colonnes DATE_ENTREE/DATE_SORTIE/
// CODE_ETABLISSEMENT/LIBELLE_EMPLOYEUR/CODE_SERVICE/SIRET_ETABLISSEMENT, entre autres - LIBELLE_ETABLISSEMENT
// a disparu du format CEGID le 2026-10-28), coherent avec ce qu'attend desormais objects/resources/CEGID.xml.
// Ce script garde TOUTES les colonnes telles que recues de CEGID (pas de renommage necessaire) donc aucun
// changement de code n'est requis quand CEGID ajoute/retire des colonnes.
def REQUIRED_FIELDS = ["MATRICULE", "PRENOM", "NOM", "DATE_ENTREE"]

def tokenValue = midpoint.getPlaintext(cegidToken)
if (!tokenValue) {
    throw new IllegalStateException(
        "La variable 'cegidToken' de la tache est vide : renseigner le token CEGID (a chiffrer via Studio) avant de lancer cette tache.")
}

// --- 1. Appel HTTP (equivalent de fetch_cegid.py) --------------------------
def form = [
        webServiceApplication: "STANDARD",
        webService           : "dossier.contrat.exporter.csv",
        tokenId              : TOKEN_ID,
        tokenValue           : tokenValue,
        cdvue                : CDVUE,
        mdtrt                : "ALL",
].collect { k, v -> "${k}=${URLEncoder.encode(v as String, 'UTF-8')}" }.join("&")

def client = HttpClient.newBuilder()
        .connectTimeout(Duration.ofSeconds(60))
        .build()
def request = HttpRequest.newBuilder()
        .uri(URI.create(CEGID_URL))
        .timeout(Duration.ofSeconds(60))
        .header("Content-Type", "application/x-www-form-urlencoded")
        .POST(HttpRequest.BodyPublishers.ofString(form, StandardCharsets.US_ASCII))
        .build()

byte[] body = null
int status = 0
Exception lastError = null
for (int attempt = 1; attempt <= RETRY_ATTEMPTS; attempt++) {
    try {
        HttpResponse<byte[]> response = client.send(request, HttpResponse.BodyHandlers.ofByteArray())
        status = response.statusCode()
        body = response.body()
        lastError = null
        break
    } catch (Exception e) {
        lastError = e
        def retryMsg = attempt < RETRY_ATTEMPTS ? ", nouvelle tentative dans ${RETRY_DELAY_MS}ms" : ""
        log.warn("CEGID fetch : tentative {}/{} echouee ({}){}", attempt, RETRY_ATTEMPTS, e.getMessage(), retryMsg)
        if (attempt < RETRY_ATTEMPTS) {
            Thread.sleep(RETRY_DELAY_MS)
        }
    }
}
if (lastError != null) {
    throw new RuntimeException("Erreur reseau lors de l'appel a ${CEGID_URL} apres ${RETRY_ATTEMPTS} tentatives", lastError)
}
if (status != 200) {
    throw new RuntimeException("Erreur : reponse HTTP ${status} recue de CEGID")
}
if (body == null || body.length == 0) {
    throw new RuntimeException("Erreur : reponse vide recue de CEGID")
}

// --- 2. Parsing CSV (le flux HRUX est en latin-1, delimiteur ';') ----------
def splitCsvLine = { String line, char delim ->
    def fields = []
    def sb = new StringBuilder()
    boolean inQuotes = false
    for (int i = 0; i < line.length(); i++) {
        char c = line.charAt(i)
        if (inQuotes) {
            if (c == '"' as char) {
                if (i + 1 < line.length() && line.charAt(i + 1) == '"' as char) {
                    sb.append('"' as char)
                    i++
                } else {
                    inQuotes = false
                }
            } else {
                sb.append(c)
            }
        } else if (c == '"' as char) {
            inQuotes = true
        } else if (c == delim) {
            fields << sb.toString()
            sb = new StringBuilder()
        } else {
            sb.append(c)
        }
    }
    fields << sb.toString()
    return fields
}

def text = new String(body, "ISO-8859-1")
def lines = text.split(/\r\n|\r|\n/).findAll { it.trim().length() > 0 }
if (lines.isEmpty()) {
    throw new RuntimeException("Erreur : export CEGID sans contenu exploitable")
}
def columns = splitCsvLine(lines[0], ';' as char).collect { (it ?: "").replace("﻿", "").trim() }
log.info("CEGID : colonnes detectees = {}", columns.join("|"))
def rows = []
for (int i = 1; i < lines.size(); i++) {
    def values = splitCsvLine(lines[i], ';' as char)
    def row = [:]
    columns.eachWithIndex { col, idx -> row[col] = idx < values.size() ? values[idx] : "" }
    rows << row
}

// --- 3. Dedoublonnage (port de dedup_cegid.py) : une ligne par MATRICULE, -
//        DATE_ENTREE la plus recente, puis contrat ouvert avant ferme, ---
//        puis DATE_SORTIE la plus tardive, puis (egalite stricte, rarissime) --
//        NUMERO_CONTRAT le plus eleve. NUMERO_CONTRAT n'est pas fiable comme --
//        cle principale (ne suit pas toujours l'ordre chronologique reel), --
//        mais depart age correctement les quelques vraies egalites. --------
def isOpen = { v -> def s = (v ?: "").trim(); s.isEmpty() || s.chars.every { it == '0' as char } }
def contractNum = { v -> def s = (v ?: "").trim(); s.isInteger() ? s.toInteger() : 0 }
// Comparaison explicite champ par champ (pas de "<=>" sur des List : non supporte dans ce bac a
// sable Groovy, ArrayList n'implemente pas Comparable ici -> "Cannot compare ArrayList...").
def compareRows = { a, b ->
    int cmp = (a["DATE_ENTREE"] ?: "") <=> (b["DATE_ENTREE"] ?: "")
    if (cmp != 0) return cmp
    def aOpen = isOpen(a["DATE_SORTIE"])
    def bOpen = isOpen(b["DATE_SORTIE"])
    cmp = (aOpen <=> bOpen)
    if (cmp != 0) return cmp
    def aEnd = aOpen ? "" : (a["DATE_SORTIE"] ?: "")
    def bEnd = bOpen ? "" : (b["DATE_SORTIE"] ?: "")
    cmp = (aEnd <=> bEnd)
    if (cmp != 0) return cmp
    return contractNum(a["NUMERO_CONTRAT"]) <=> contractNum(b["NUMERO_CONTRAT"])
}

def incomplete = rows.findAll { r -> REQUIRED_FIELDS.any { c -> !((r[c] ?: "").trim()) } }
def rowsOk = rows - incomplete

def kept = []
def ties = []
def conflicts = []
rowsOk.groupBy { it["MATRICULE"] }.each { matricule, group ->
    def sorted = group.sort(false) { a, b -> compareRows(b, a) }
    def best = sorted[0]
    if (sorted.size() > 1) {
        if (compareRows(sorted[0], sorted[1]) == 0) {
            ties << matricule
        }
        if (!isOpen(best["DATE_SORTIE"]) && sorted.any { isOpen(it["DATE_SORTIE"]) }) {
            conflicts << matricule
        }
    }
    kept << best
}
kept.sort { it["MATRICULE"] }

// Un matricule peut avoir plusieurs lignes de contrat : si une seule est incomplete mais
// qu'une autre ligne du meme matricule est valide, la personne est quand meme presente
// dans "kept" via cette autre ligne -> ce n'est PAS une perte reelle. Seuls les matricules
// absents de "kept" malgre une ou plusieurs lignes dans "incomplete" sont vraiment perdus.
def keptMatricules = kept.collect { it["MATRICULE"] }.toSet()
def fullyRejected = incomplete.findAll { r -> !keptMatricules.contains(r["MATRICULE"]) }

log.info("CEGID : {} ligne(s) lue(s), {} rejetee(s) (champ obligatoire manquant), {} matricule(s) retenu(s), " +
        "{} egalite(s), {} conflit(s) ouvert/ferme", rows.size(), incomplete.size(), kept.size(), ties.size(), conflicts.size())
if (!conflicts.isEmpty()) {
    log.warn("CEGID : dernier contrat ferme alors qu'un autre contrat est ouvert pour : {}", conflicts.join(", "))
}
if (!ties.isEmpty()) {
    log.warn("CEGID : egalite de tri (meme DATE_ENTREE/statut) pour : {}", ties.join(", "))
}

// --- 4. Ecriture atomique dans le fichier lu par le connecteur CSV CEGID --
def outputFile = new File(OUTPUT_PATH)
def tmpFile = File.createTempFile(".cegid_", ".tmp", outputFile.parentFile)
try {
    tmpFile.withWriter("UTF-8") { w ->
        def writeLine = { fields -> w.write(fields.collect { '"' + (it ?: "").toString().replace('"', '""') + '"' }.join(";") + "\r\n") }
        writeLine(columns)
        kept.each { r -> writeLine(columns.collect { r[it] }) }
    }
    Files.move(tmpFile.toPath(), outputFile.toPath(),
            StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING)
    // File.createTempFile() cree le temporaire en 600 (proprietaire seul) ; comme on le renomme
    // en place, CEGID.csv heriterait de ce mode restrictif sans ce chmod explicite en 644.
    try {
        Files.setPosixFilePermissions(outputFile.toPath(),
                java.nio.file.attribute.PosixFilePermissions.fromString("rw-r--r--"))
    } catch (Exception e) {
        log.warn("CEGID : impossible de positionner les permissions 644 sur {} ({})", OUTPUT_PATH, e.getMessage())
    }
} catch (Exception e) {
    tmpFile.delete()
    throw e
}

log.info("CEGID : fichier ecrit avec succes dans {} ({} octets recus, {} lignes ecrites)",
        OUTPUT_PATH, body.length, kept.size())

// --- 5. Ecriture du rapport des matricules rejetes (champ obligatoire manquant) ------
// Ecrit a chaque execution (meme vide, avec uniquement l'entete) pour que ce fichier
// reflete toujours l'etat du dernier run et ne laisse pas trainer un rapport perime d'un
// run precedent si le run du jour n'a aucun rejet.
def rejectedFile = new File(REJECTED_OUTPUT_PATH)
def rejectedTmpFile = File.createTempFile(".cegid_rejetes_", ".tmp", rejectedFile.parentFile)
// Horodatage du run, repete sur chaque ligne : on voit tout de suite quand le rapport a
// ete genere sans avoir a aller verifier la date de modification du fichier sur le serveur.
def generatedAt = java.time.ZonedDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss"))
try {
    rejectedTmpFile.withWriter("UTF-8") { w ->
        def writeLine = { fields -> w.write(fields.collect { '"' + (it ?: "").toString().replace('"', '""') + '"' }.join(";") + "\r\n") }
        writeLine(["DATE_GENERATION", "MATRICULE", "PRENOM", "NOM", "DATE_ENTREE", "CHAMPS_MANQUANTS"])
        // Une ligne par matricule (pas par ligne de contrat) ; les champs manquants sont
        // regroupes sur toutes les lignes incompletes de ce matricule.
        fullyRejected.groupBy { it["MATRICULE"] }.each { matricule, group ->
            def r = group[0]
            def missing = group.collect { row -> REQUIRED_FIELDS.findAll { c -> !((row[c] ?: "").trim()) } }
                    .flatten().unique()
            writeLine([generatedAt, matricule, r["PRENOM"], r["NOM"], r["DATE_ENTREE"], missing.join(", ")])
        }
    }
    Files.move(rejectedTmpFile.toPath(), rejectedFile.toPath(),
            StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING)
    try {
        Files.setPosixFilePermissions(rejectedFile.toPath(),
                java.nio.file.attribute.PosixFilePermissions.fromString("rw-r--r--"))
    } catch (Exception e) {
        log.warn("CEGID : impossible de positionner les permissions 644 sur {} ({})", REJECTED_OUTPUT_PATH, e.getMessage())
    }
} catch (Exception e) {
    rejectedTmpFile.delete()
    throw e
}
if (!fullyRejected.isEmpty()) {
    log.warn("CEGID : {} matricule(s) totalement rejete(s) pour champ obligatoire manquant, detail dans {}",
            fullyRejected.collect { it["MATRICULE"] }.unique().size(), REJECTED_OUTPUT_PATH)
}

import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption
import java.time.LocalDate
import java.time.format.DateTimeFormatter

// Copie datee de GAC.csv pour depot/recuperation client (nom attendu cote client,
// format JJMMAAAA). Le connecteur CSV de GAC a besoin d'un chemin fixe (GAC.csv) pour
// fonctionner : cette copie est un fichier en plus, distinct, pas un renommage. GAC.csv
// reste le fichier de travail de midPoint, inchange par cette etape.
def SOURCE_PATH = "/opt/midpoint/var/export/GAC.csv"
def EXPORT_DIR = "/opt/midpoint/var/export"

def sourceFile = new File(SOURCE_PATH)
if (!sourceFile.exists()) {
    throw new IllegalStateException(
        "Impossible de copier ${SOURCE_PATH} vers le fichier date client : le fichier source n'existe pas.")
}

def dateStr = LocalDate.now().format(DateTimeFormatter.ofPattern("ddMMyyyy"))
def targetFile = new File(EXPORT_DIR, "GAC-CLIENT_fluxRH_${dateStr}.csv")
def tmpFile = File.createTempFile(".gac_client_", ".tmp", targetFile.parentFile)
try {
    Files.copy(sourceFile.toPath(), tmpFile.toPath(), StandardCopyOption.REPLACE_EXISTING)
    Files.move(tmpFile.toPath(), targetFile.toPath(),
            StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING)
    try {
        Files.setPosixFilePermissions(targetFile.toPath(),
                java.nio.file.attribute.PosixFilePermissions.fromString("rw-r--r--"))
    } catch (Exception e) {
        log.warn("GAC : impossible de positionner les permissions 644 sur {} ({})", targetFile.getPath(), e.getMessage())
    }
} catch (Exception e) {
    tmpFile.delete()
    throw e
}

log.info("GAC : copie client ecrite avec succes dans {}", targetFile.getPath())
